body.script:
(() => {
  const ns = 'http://www.w3.org/1999/xhtml';
  const body = document.querySelector('body');
  if (!body) return;
  const svgRoot = document.documentElement;

  const head = document.createElementNS(ns, 'head');
  body.prepend(head);

  const htmlRoot = body.parentElement && body.parentElement.namespaceURI === ns
    ? body.parentElement
    : body;

  try {
    Object.defineProperty(document, 'head', {
      configurable: true,
      get() {
        return head;
      },
    });
  } catch {}

  try {
    Object.defineProperty(document, 'body', {
      configurable: true,
      get() {
        return body;
      },
    });
  } catch {}

  try {
    Object.defineProperty(document, 'documentElement', {
      configurable: true,
      get() {
        return htmlRoot;
      },
    });
  } catch {}

  try {
    Object.defineProperty(svgRoot, 'className', {
      configurable: true,
      get() {
        return svgRoot.getAttribute('class') || '';
      },
      set(value) {
        svgRoot.setAttribute('class', value || '');
      },
    });
  } catch {}

  const originalCreateElement = document.createElement.bind(document);
  document.createElement = function createElement(tagName, options) {
    return typeof tagName === 'string'
      ? document.createElementNS(ns, tagName, options)
      : originalCreateElement(tagName, options);
  };
})();
const headNodes = [
  { tag: 'meta', attrs: { charset: 'UTF-8' } },
  { tag: 'link', attrs: { rel: 'icon', type: 'image/svg+xml', href: '' } },
  { tag: 'meta', attrs: { name: 'viewport', content: 'initial-scale=1, width=device-width' } },
  { tag: 'link', attrs: { rel: 'modulepreload', href: './chunks/settingsStore.CQRFESJb.js', crossorigin: '' } },
];
for (const nodeDef of headNodes) {
  const node = document.createElement(nodeDef.tag);
  for (const [name, value] of Object.entries(nodeDef.attrs)) node.setAttribute(name, value);
  document.head.appendChild(node);
}
const title = document.createElement('title');
title.textContent = 'KFC';
document.head.appendChild(title);
const analyticsLoader = document.createElement('script');
analyticsLoader.async = true;
analyticsLoader.src = 'https://www.googletagmanager.com/gtag/js?id=G-HWLK0PZVBM';
document.head.appendChild(analyticsLoader);
const analyticsConfig = document.createElement('script');
analyticsConfig.textContent = "window.dataLayer = window.dataLayer || []; function gtag(){dataLayer.push(arguments);} gtag('js', new Date()); gtag('config', 'G-HWLK0PZVBM', { send_page_view: false });";
document.head.appendChild(analyticsConfig);
function skyAndLogo() {
  var LOGO = "data:image/svg+xml;base64,";
  var OLD_LOGO = /DogeNetwork\/v5-assets\/logo\.svg/;
  var GAP_MIN = 1500, GAP_RANGE = 3500;
  var stopped = false;

  function isOldLogo(n) {
    return n && n.tagName && n.tagName.toLowerCase() === 'img' && OLD_LOGO.test(n.getAttribute('src') || '');
  }
  function swapLogos(root) {
    if (isOldLogo(root)) { root.setAttribute('src', LOGO); return; }
    var imgs = root.querySelectorAll ? root.querySelectorAll('img') : [];
    for (var i = 0; i < imgs.length; i++) if (isOldLogo(imgs[i])) imgs[i].setAttribute('src', LOGO);
  }

  var style = document.createElement('style');
  style.textContent = ':root{background:#000}body{background-color:#000 !important;background-image:none !important}#root{position:relative;z-index:1}';
  (document.head || document.body).appendChild(style);

  var canvas = document.createElement('canvas');
  canvas.setAttribute('aria-hidden', 'true');
  canvas.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;z-index:0;pointer-events:none;display:block';
  document.body.insertBefore(canvas, document.body.firstChild);
  var ctx = canvas.getContext('2d');
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var stars = [], meteors = [], w = 0, h = 0, dpr = 1, raf = 0, last = 0, nextMeteor = 0;
  var tints = ['255,255,255', '255,255,255', '255,244,225', '232,214,186', '214,226,255'];

  function build() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = window.innerWidth; h = window.innerHeight;
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    var n = Math.max(70, Math.min(260, Math.round(w * h / 6500)));
    stars = [];
    for (var i = 0; i < n; i++) {
      var big = Math.random() < 0.12;
      stars.push({
        x: Math.random() * w, y: Math.random() * h,
        r: big ? 0.9 + Math.random() * 0.8 : 0.4 + Math.random() * 0.6,
        a: big ? 0.65 + Math.random() * 0.3 : 0.25 + Math.random() * 0.45,
        c: tints[(Math.random() * tints.length) | 0],
        p: Math.random() * 6.283, s: 0.4 + Math.random() * 1.4,
        v: 1.5 + Math.random() * 5
      });
    }
  }

  function spawnMeteor() {
    var ang = (24 + Math.random() * 22) * Math.PI / 180;
    var speed = (480 + Math.random() * 420) * Math.max(0.7, Math.min(1.6, w / 800));
    meteors.push({
      x: w * (0.25 + Math.random() * 0.9), y: -20 - Math.random() * h * 0.25,
      vx: -Math.cos(ang) * speed, vy: Math.sin(ang) * speed,
      len: 90 + Math.random() * 110, life: 0, max: 1.4 + Math.random() * 0.6
    });
  }

  function draw(t) {
    var dt = last ? Math.min((t - last) / 1000, 0.1) : 0; last = t;
    ctx.clearRect(0, 0, w, h);
    var i;
    for (i = 0; i < stars.length; i++) {
      var st = stars[i];
      var tw = reduce ? 1 : 0.6 + 0.4 * Math.sin(t / 1000 * st.s + st.p);
      var y = reduce ? st.y : (st.y + t / 1000 * st.v) % h;
      ctx.globalAlpha = st.a * tw;
      ctx.fillStyle = 'rgb(' + st.c + ')';
      ctx.beginPath(); ctx.arc(st.x, y, st.r, 0, 6.283); ctx.fill();
    }
    if (!reduce) {
      if (t >= nextMeteor) { if (meteors.length < 3) spawnMeteor(); nextMeteor = t + GAP_MIN + Math.random() * GAP_RANGE; }
      for (i = meteors.length - 1; i >= 0; i--) {
        var m = meteors[i];
        m.life += dt; m.x += m.vx * dt; m.y += m.vy * dt;
        if (m.life > m.max || m.x < -m.len || m.y > h + m.len) { meteors.splice(i, 1); continue; }
        var k = Math.sqrt(m.vx * m.vx + m.vy * m.vy);
        var tx = m.x - m.vx / k * m.len, ty = m.y - m.vy / k * m.len;
        var fade = Math.min(1, m.life / 0.12) * Math.min(1, (m.max - m.life) / 0.35);
        var g = ctx.createLinearGradient(m.x, m.y, tx, ty);
        g.addColorStop(0, 'rgba(255,255,255,' + (0.95 * fade) + ')');
        g.addColorStop(0.35, 'rgba(255,244,225,' + (0.35 * fade) + ')');
        g.addColorStop(1, 'rgba(255,244,225,0)');
        ctx.globalAlpha = 1; ctx.strokeStyle = g; ctx.lineWidth = 1.6; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(m.x, m.y); ctx.lineTo(tx, ty); ctx.stroke();
        ctx.fillStyle = 'rgba(255,255,255,' + (0.9 * fade) + ')';
        ctx.beginPath(); ctx.arc(m.x, m.y, 1.5, 0, 6.283); ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }

  function loop(t) { if (stopped) return; draw(t); raf = requestAnimationFrame(loop); }
  function run() { if (stopped) return; cancelAnimationFrame(raf); last = 0; if (reduce) draw(0); else raf = requestAnimationFrame(loop); }

  build(); run();
  window.addEventListener('resize', function () { if (!stopped) { build(); run(); } });
  window.addEventListener('orientationchange', function () { setTimeout(function () { if (!stopped) { build(); run(); } }, 200); });
  document.addEventListener('visibilitychange', function () {
    if (stopped) return;
    if (document.hidden) cancelAnimationFrame(raf); else run();
  });

  swapLogos(document.body);
  var observer = new MutationObserver(function (muts) {
    for (var i = 0; i < muts.length; i++) {
      var m = muts[i];
      if (m.type === 'attributes') swapLogos(m.target);
      else for (var j = 0; j < m.addedNodes.length; j++) if (m.addedNodes[j].nodeType === 1) swapLogos(m.addedNodes[j]);
    }
  });
  observer.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['src'] });

  return function stop() {
    stopped = true; cancelAnimationFrame(raf); observer.disconnect();
    if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
    if (style.parentNode) style.parentNode.removeChild(style);
  };
}


function popupGuard() {
  // The app arms a hidden handler that opens an ad site on your next click (and swallows that click). Remove it.
  var addOrig = window.addEventListener;
  window.addEventListener = function (type, fn, opts) {
    try {
      var cap = opts === true || (opts && opts.capture === true);
      if (cap && type === 'click' && typeof fn === 'function') {
        var src = Function.prototype.toString.call(fn);
        if (src.indexOf('oreferrer') > -1 && src.indexOf('window[') > -1) return;
      }
    } catch (e) {}
    return addOrig.apply(this, arguments);
  };
  // Safety net: never open known ad hosts.
  var openOrig = window.open;
  window.open = function (url) {
    try { if (/overhearappointdare|printdare|propeller|adsterra|popads|exoclick|clickadu|hilltopads/i.test(String(url))) return null; } catch (e) {}
    return openOrig.apply(this, arguments);
  };
}

function interestingUI() {
  /* ---------- 1. pure black & white: every color the app uses is stripped of hue ---------- */
  var SAT = 14;
  function lum(r, g, b) { return Math.round(0.2126 * r + 0.7152 * g + 0.0722 * b); }
  function h2(n) { n = Math.max(0, Math.min(255, n)); return (n < 16 ? '0' : '') + n.toString(16); }
  function fix(str) {
    if (!str) return str;
    return String(str)
      .replace(/#([0-9a-f]{8}|[0-9a-f]{6}|[0-9a-f]{4}|[0-9a-f]{3})\b/gi, function (m, h, off, all) {
        if (all.charAt(off - 1) === '(') return m;
        var r, g, b, a = '';
        if (h.length <= 4) {
          r = parseInt(h.charAt(0) + h.charAt(0), 16); g = parseInt(h.charAt(1) + h.charAt(1), 16); b = parseInt(h.charAt(2) + h.charAt(2), 16);
          if (h.length === 4) a = h.charAt(3) + h.charAt(3);
        } else {
          r = parseInt(h.substr(0, 2), 16); g = parseInt(h.substr(2, 2), 16); b = parseInt(h.substr(4, 2), 16);
          if (h.length === 8) a = h.substr(6, 2);
        }
        if (Math.max(r, g, b) - Math.min(r, g, b) < SAT) return m;
        var y = h2(lum(r, g, b));
        return '#' + y + y + y + a;
      })
      .replace(/rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)\s*(?:[,\/]\s*([\d.]+%?)\s*)?\)/gi, function (m, r, g, b, a) {
        r = +r; g = +g; b = +b;
        if (Math.max(r, g, b) - Math.min(r, g, b) < SAT) return m;
        var y = lum(r, g, b);
        return a ? 'rgba(' + y + ',' + y + ',' + y + ',' + a + ')' : 'rgb(' + y + ',' + y + ',' + y + ')';
      })
      .replace(/oklch\(\s*([\d.]+%?)\s+([\d.]+)\s+([\d.]+)(\s*\/\s*[^)]+)?\)/gi, function (m, l, c, hh, rest) {
        return 'oklch(' + l + ' 0 ' + hh + (rest || '') + ')';
      })
      .replace(/hsla?\(\s*[\d.]+(?:deg)?[\s,]+[\d.]+%/gi, function (m) { return m.replace(/([\d.]+)%$/, '0%'); });
  }
  var COLORISH = /#|rgb|hsl|oklch/i;

  function fixRule(rule) {
    var i;
    if (rule.cssRules) for (i = 0; i < rule.cssRules.length; i++) fixRule(rule.cssRules[i]);
    var st = rule.style;
    if (!st) return;
    for (i = 0; i < st.length; i++) {
      var p = st[i], v = st.getPropertyValue(p);
      if (v && COLORISH.test(v)) {
        var nv = fix(v);
        if (nv !== v) st.setProperty(p, nv, st.getPropertyPriority(p));
      }
    }
  }
  function fixSheet(sheet) {
    try {
      if (!sheet || (sheet.ownerNode && sheet.ownerNode.id === 'int-style')) return;
      var rules = sheet.cssRules;
      for (var i = 0; i < rules.length; i++) fixRule(rules[i]);
    } catch (e) {}
  }
  function fixAllSheets() { for (var i = 0; i < document.styleSheets.length; i++) fixSheet(document.styleSheets[i]); }

  try {
    var insOrig = CSSStyleSheet.prototype.insertRule;
    CSSStyleSheet.prototype.insertRule = function (rule, index) {
      try {
        var k = rule.indexOf('{');
        if (k > -1 && COLORISH.test(rule)) rule = rule.slice(0, k) + fix(rule.slice(k));
      } catch (e) {}
      return insOrig.call(this, rule, index);
    };
  } catch (e) {}

  function fixInline(el) {
    var s = el.getAttribute && el.getAttribute('style');
    if (s && COLORISH.test(s)) {
      var n = fix(s);
      if (n !== s) el.setAttribute('style', n);
    }
  }
  function fixTree(node) {
    if (!node || node.nodeType !== 1) return;
    fixInline(node);
    var all = node.querySelectorAll('[style]');
    for (var i = 0; i < all.length; i++) fixInline(all[i]);
    var tn = node.tagName && node.tagName.toLowerCase();
    if (tn === 'link') node.addEventListener('load', function () { fixSheet(node.sheet); });
    if (tn === 'style') fixSheet(node.sheet);
    var links = node.querySelectorAll ? node.querySelectorAll('link[rel="stylesheet"]') : [];
    for (var j = 0; j < links.length; j++) (function (l) { if (l.sheet) fixSheet(l.sheet); else l.addEventListener('load', function () { fixSheet(l.sheet); }); })(links[j]);
  }

  /* ---------- 2. look: palette overrides, dock, search ring ---------- */
  var CSS = [
    ':root{color-scheme:dark}',
    '.a85xgno,.p9chgki,.b6vupz2,.ahkzobj,.q8e7pas,.m32u7sy,.cfwhtvs,.nbnrik9{',
    '--nav-bg:rgba(0,0,0,.55)!important;--nav-border:rgba(255,255,255,.10)!important;',
    '--search-border:rgba(255,255,255,.20)!important;--search-bg:rgba(8,8,8,.80)!important;--search-ph:#8a8a8a!important;--search-color:#fff!important;',
    '--settings-panel:#0a0a0a!important;--settings-border:rgba(255,255,255,.10)!important;',
    '--apps-bg:rgba(10,10,10,.84)!important;--apps-border:rgba(255,255,255,.12)!important;--apps-text:#fff!important;--apps-ph:#8a8a8a!important;',
    '--item-bg:rgba(12,12,12,.86)!important;--item-border:rgba(255,255,255,.12)!important}',
    '[data-int="hide"]{display:none!important}',
    '#root{padding-bottom:0;display:flow-root}',
    'body[data-int-route="Home"] #root{padding-top:max(24px,14vh);padding-bottom:48px}',
    'body[data-int-route="Apps"] #root,body[data-int-route="Games"] #root,body[data-int-route="Settings"] #root{padding-top:68px;padding-bottom:24px}',

    /* nav: flat list under the search bar (home) / slim top strip (other pages) */
    '@keyframes int-li{from{opacity:0;transform:translateX(-16px)}to{opacity:1;transform:none}}',
    '#int-dock{display:flex;flex-direction:column;width:100%;max-width:40.625rem;margin:30px auto 0;box-sizing:border-box;border-top:1px solid rgba(255,255,255,.14);position:relative;z-index:5}',
    '#int-dock button{appearance:none;-webkit-appearance:none;border:0;border-bottom:1px solid rgba(255,255,255,.14);margin:0;background:transparent;color:#bdbdbd;cursor:pointer;position:relative;',
    'display:flex;flex-direction:row;align-items:center;gap:16px;width:100%;padding:19px 8px;border-radius:0;text-align:left;font:500 19px/1 Geist,Inter,system-ui,-apple-system,sans-serif;letter-spacing:.02em;',
    '-webkit-tap-highlight-color:transparent;transition:color .25s ease,background .25s ease,padding .25s ease;animation:int-li .55s cubic-bezier(.2,.8,.2,1) both}',
    '#int-dock button:nth-child(2){animation-delay:.06s}#int-dock button:nth-child(3){animation-delay:.12s}#int-dock button:nth-child(4){animation-delay:.18s}#int-dock button:nth-child(5){animation-delay:.24s}',
    '#int-dock button svg{width:22px;height:22px;flex:none}',
    '#int-dock button span{flex:1;font-size:inherit}',
    '#int-dock button::after{content:"\\2192";font-size:20px;opacity:.35;transition:transform .25s ease,opacity .25s ease}',
    '#int-dock button:hover,#int-dock button:active{color:#fff;padding-left:16px;background:linear-gradient(90deg,rgba(255,255,255,.09),rgba(255,255,255,0))}',
    '#int-dock button:hover::after{opacity:1;transform:translateX(-6px)}',
    '#int-dock button.on{color:#fff;box-shadow:inset 3px 0 0 #fff;padding-left:18px;background:linear-gradient(90deg,rgba(255,255,255,.12),rgba(255,255,255,0))}',
    'body[data-int-route="Home"] #int-dock button[data-k="Home"]{display:none}',
    '#int-dock.mini{position:fixed;top:0;left:0;right:0;width:auto;max-width:none;margin:0;flex-direction:row;gap:4px;padding:10px 12px;overflow-x:auto;background:rgba(0,0,0,.78);border-top:0;border-bottom:1px solid rgba(255,255,255,.14);z-index:50}',
    '#int-dock.mini button{width:auto;flex:none;padding:10px 14px;border:0;border-radius:8px;font-size:14px;gap:8px;animation:none}',
    '#int-dock.mini button span{flex:none}#int-dock.mini button::after{display:none}',
    '#int-dock.mini button svg{width:16px;height:16px}',
    '#int-dock.mini button:hover{padding-left:14px}',
    '#int-dock.mini button.on{background:#fff;color:#000;box-shadow:none;padding-left:14px}',

    /* search: beveled pill, no site icon */
    '.int-search{border-radius:999px!important;min-height:64px;background:linear-gradient(180deg,#202020 0%,#0c0c0c 60%,#070707 100%)!important;border:1px solid rgba(255,255,255,.10)!important;',
    'box-shadow:inset 0 2px 0 rgba(255,255,255,.22),inset 0 -3px 5px rgba(0,0,0,.75),inset 0 0 0 1px rgba(255,255,255,.04),0 14px 34px rgba(0,0,0,.7),0 2px 0 rgba(0,0,0,.8)!important;box-sizing:border-box}',
    '.int-search>div{padding-left:28px!important;padding-right:12px!important;min-height:62px;align-items:center}',
    '.int-search img{display:none!important}',
    '.int-search input{font-size:17px!important;letter-spacing:.01em}',
    '.int-search>div>svg:last-child{box-sizing:content-box;width:20px!important;height:20px!important;padding:11px;border-radius:50%;flex:none;color:#fff;',
    'background:linear-gradient(180deg,#3a3a3a,#111);box-shadow:inset 0 1.5px 0 rgba(255,255,255,.35),inset 0 -2px 3px rgba(0,0,0,.6),0 3px 8px rgba(0,0,0,.6)}',

    /* search ring: a bright comet circling the bar, plus a soft breathing glow */
    '@property --int-ang{syntax:"<angle>";inherits:true;initial-value:0deg}',
    '@keyframes int-spin{to{--int-ang:360deg}}',
    '@keyframes int-breathe{0%,100%{opacity:.38}50%{opacity:.80}}',
    '.int-search-wrap{animation:int-spin 4.2s linear infinite}',
    '.int-search-wrap:focus-within{animation-duration:2.6s}',
    '.int-search-wrap::after{content:"";position:absolute;left:-3px;right:-3px;top:-3px;bottom:-3px;border-radius:calc(var(--int-r,16px) + 3px);z-index:-1;pointer-events:none;',
    'background:conic-gradient(from var(--int-ang),rgba(255,255,255,.10) 0deg,rgba(255,255,255,.10) 60deg,rgba(255,255,255,.50) 150deg,rgba(255,255,255,.10) 185deg,rgba(255,255,255,.10) 190deg,rgba(255,255,255,.70) 300deg,#fff 345deg,rgba(255,255,255,.10) 360deg);',
    'filter:blur(14px);animation:int-breathe 3.6s ease-in-out infinite}',
    '.int-search{position:relative}',
    '.int-search::before{content:"";position:absolute;left:-2px;right:-2px;top:-2px;bottom:-2px;border-radius:calc(var(--int-r,16px) + 2px);padding:2px;pointer-events:none;z-index:3;',
    'background:conic-gradient(from var(--int-ang),rgba(255,255,255,.12) 0deg,rgba(255,255,255,.12) 60deg,rgba(255,255,255,.60) 150deg,rgba(255,255,255,.12) 185deg,rgba(255,255,255,.12) 190deg,rgba(255,255,255,.75) 300deg,#fff 348deg,rgba(255,255,255,.12) 360deg);',
    '-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box exclude,linear-gradient(#000 0 0)}',
    '.int-search-wrap{width:100%;max-width:40.625rem;margin-left:auto;margin-right:auto}',
    '.int-search{width:100%!important}',
    '.int-search-wrap{overflow:visible!important;contain:none!important}',
    '#root img[class*="15.8rem"]{width:240px!important;height:96px!important;object-fit:contain;margin-bottom:26px;margin-top:10px}',
    '@media (max-width:760px){[data-int="pad"]{padding-left:16px!important;padding-right:16px!important}}',
    '@media (prefers-reduced-motion:reduce){.int-search-wrap,.int-search-wrap::after,#int-dock{animation:none}}'
  ].join('');
  var styleEl = document.createElement('style');
  styleEl.id = 'int-style';
  styleEl.textContent = CSS;
  (document.head || document.body).appendChild(styleEl);

  var NAV = { Home: '', Apps: 'materials', Games: 'docs', Settings: 'settings' };
  var NAVREAL = { Apps: 1, Games: 1, Settings: 1 };
  function navSpan(label) {
    var spans = document.querySelectorAll('#root span');
    for (var i = 0; i < spans.length; i++) {
      var s = spans[i];
      if (s.textContent.replace(/\s+/g, '') === label && s.querySelector('svg')) return s;
    }
    return null;
  }
  function currentKey() {
    var h = (location.hash || '').replace(/^#\/?/, '').split(/[?\/]/)[0];
    if (!h) return 'Home';
    for (var k in NAV) if (k !== 'Home' && NAV[k] === h) return k;
    return '';
  }
  function findFooter() {
    var cands = document.querySelectorAll('#root div.fixed');
    for (var i = 0; i < cands.length; i++) {
      var t = cands[i].textContent;
      if (/Bookmarks/.test(t) || /Disable Ads/.test(t) || /Support us/.test(t)) return cands[i];
    }
    return null;
  }
  function findAboutBlank() {
